"""Build the mkdocs nav list from a ProjectSnapshot."""

from __future__ import annotations

from harness.site.discovery import FeatureState, ProjectSnapshot


def build_nav(snap: ProjectSnapshot, *, include_internal: bool = False) -> list:
    """Return a list suitable for serialisation under `nav:` in mkdocs.yml.

    Each entry is either `{"<title>": "<path>"}` or `{"<title>": [...children]}`.
    """
    nav: list = [{"Home": "index.md"}]

    # Overview group — status board + RTM + activity + KPI
    overview: list = [{"Status board": "status.md"}]
    if snap.rtm_path:
        overview.append({"Requirements traceability": "rtm.md"})
    if snap.activity_paths:
        overview.append({"Activity feed": "activity.md"})
        overview.append({"KPI dashboard": "kpi.md"})
    nav.append({"Overview": overview})

    # Features group
    if snap.features:
        features_nav: list = [{"All features": "features/index.md"}]
        for fid in sorted(snap.features):
            fs = snap.features[fid]
            features_nav.append({f"{fid} {fs.title}": _feature_subnav(fs)})
        nav.append({"Features": features_nav})

    # Decisions (ADRs)
    if snap.adr_paths:
        adr_nav: list = [{"Index": "adr/index.md"}]
        for p in snap.adr_paths:
            adr_nav.append({_adr_title(p.stem): f"adr/{p.name}"})
        nav.append({"Decisions (ADRs)": adr_nav})

    # Process
    process: list = []
    if snap.session_paths:
        process.append({"Sessions": "sessions/index.md"})
    if snap.config_paths:
        process.append({"Configuration": "config/index.md"})
    if process:
        nav.append({"Process": process})

    # Reference (internal only)
    if include_internal and snap.rule_paths:
        nav.append({"Reference": [{"Internal rules": "reference/rules.md"}]})

    return nav


def _feature_subnav(fs: FeatureState) -> list:
    """Per-feature subnav. Only includes pages whose source artifact exists."""
    sub: list = [{"Summary": f"features/{fs.feature_id}/index.md"}]
    if fs.story_path:
        sub.append({"Story": f"features/{fs.feature_id}/story.md"})
    if fs.research_path:
        sub.append({"Research": f"features/{fs.feature_id}/research.md"})
    if fs.requirements_path:
        sub.append({"Requirements": f"features/{fs.feature_id}/requirements.md"})
    if fs.plan_path:
        sub.append({"Plan": f"features/{fs.feature_id}/plan.md"})
    if fs.validation_path:
        sub.append({"Validation": f"features/{fs.feature_id}/validation.md"})
    if fs.review_path:
        sub.append({"Review": f"features/{fs.feature_id}/review.md"})
    if fs.test_cases_path:
        sub.append({"Test cases": f"features/{fs.feature_id}/tests.md"})
    if fs.design_path or fs.design_dir:
        sub.append({"Design": f"features/{fs.feature_id}/design.md"})
    if fs.runbook_paths:
        sub.append({"Runbooks": f"features/{fs.feature_id}/runbooks.md"})
    # State-driven pages (decisions / clarifications / agent flags) appear
    # only when the corresponding state arrays are non-empty.
    if fs.raw.get("decisions"):
        sub.append({"Decisions": f"features/{fs.feature_id}/decisions.md"})
    if fs.raw.get("clarifications"):
        sub.append({"Clarifications": f"features/{fs.feature_id}/clarifications.md"})
    if fs.raw.get("agent_flags"):
        sub.append({"Agent flags": f"features/{fs.feature_id}/flags.md"})
    impl_evidence = fs.raw.get("impl_evidence") or {}
    if impl_evidence.get("checks"):
        sub.append({"Evidence": f"features/{fs.feature_id}/evidence.md"})
    if fs.evidence_rounds_path:
        sub.append({"Evidence rounds": f"features/{fs.feature_id}/evidence-rounds.md"})
    if fs.evidence_escalation_path:
        sub.append({"Evidence escalation": f"features/{fs.feature_id}/evidence-escalation.md"})
    return sub


def _adr_title(stem: str) -> str:
    """`0007-token-storage` → `0007 — Token storage`."""
    if "-" in stem:
        num, _, slug = stem.partition("-")
        return f"{num} — {slug.replace('-', ' ').capitalize()}"
    return stem
